[CmdletBinding()]
param([Parameter(Mandatory)][string] $GateScript)
$ErrorActionPreference = 'Stop'
$global:GateScriptRoot = Split-Path -Parent (Resolve-Path $GateScript)
function Assert-True([bool] $Condition, [string] $Message) { if (-not $Condition) { throw $Message } }
function Get-Only { $h=@{}; Get-ChildItem Env: | Where-Object {$_.Name -match '^ARPG_.*_ONLY$'} | ForEach-Object {$h[$_.Name]=$_.Value}; $h }
function Set-Only([hashtable] $Values) { Get-ChildItem Env: | Where-Object {$_.Name -match '^ARPG_.*_ONLY$'} | ForEach-Object {Remove-Item "Env:$($_.Name)"}; foreach($e in $Values.GetEnumerator()){Set-Item "Env:$($e.Key)" $e.Value} }
function Assert-Only([hashtable]$Expected,[hashtable]$Actual) { Assert-True ($Expected.Count -eq $Actual.Count) 'environment count changed'; foreach($e in $Expected.GetEnumerator()){Assert-True ($Actual.ContainsKey($e.Key) -and $Actual[$e.Key] -ceq $e.Value) "environment changed: $($e.Key)"} }
$tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $GateScript),[ref]$tokens,[ref]$errors);if($errors.Count){throw "Gate parse errors: $($errors.Message -join '; ')"}
function Assert-TopLevelGateInvocation($ScriptAst) { $topTries=@($ScriptAst.FindAll({param($n) if($n -isnot [System.Management.Automation.Language.TryStatementAst]){return $false};$cursor=$n.Parent;while($null -ne $cursor){if($cursor -is [System.Management.Automation.Language.FunctionDefinitionAst]){return $false};$cursor=$cursor.Parent};return $true},$true));Assert-True ($topTries.Count -eq 1) 'exactly one top-level aggregate try body is required';$body=$topTries[0].Body;$calls=@($body.FindAll({param($n) if($n -isnot [System.Management.Automation.Language.CommandAst] -or $n.GetCommandName() -cne 'Invoke-InventoryProgressionGate'){return $false};$cursor=$n.Parent;while($null -ne $cursor -and $cursor -ne $body){if($cursor -is [System.Management.Automation.Language.FunctionDefinitionAst] -or $cursor -is [System.Management.Automation.Language.IfStatementAst] -or $cursor -is [System.Management.Automation.Language.ForStatementAst] -or $cursor -is [System.Management.Automation.Language.ForEachStatementAst] -or $cursor -is [System.Management.Automation.Language.WhileStatementAst] -or $cursor -is [System.Management.Automation.Language.DoWhileStatementAst] -or $cursor -is [System.Management.Automation.Language.DoUntilStatementAst] -or $cursor -is [System.Management.Automation.Language.SwitchStatementAst] -or $cursor -is [System.Management.Automation.Language.TrapStatementAst] -or $cursor -is [System.Management.Automation.Language.CatchClauseAst]){return $false};$cursor=$cursor.Parent};return $true},$true));Assert-True ($calls.Count -eq 1) 'top-level aggregate recipe invocation is missing or duplicated';Assert-True ($calls[0].CommandElements.Count -eq 6) 'top-level aggregate recipe must receive five arguments';$actual=@($calls[0].CommandElements|ForEach-Object {$_.Extent.Text});$expected=@('Invoke-InventoryProgressionGate','$root','$Preset','$platform',"(Join-Path `$PSScriptRoot 'full_chinese_inventory_progression_gate_self_test.ps1')","(Join-Path `$PSScriptRoot 'full_chinese_inventory_selector_self_test.ps1')");Assert-True (($actual -join '|') -ceq ($expected -join '|')) 'top-level aggregate recipe arguments changed' }
