function Invoke-ArpgNative { param([string]$FilePath,[string[]]$ArgumentList=@());$script:Calls.Add([pscustomobject]@{File=$FilePath;Args=@($ArgumentList)});if($script:Mode -eq 'native-error'){throw 'native fixture error'};if($FilePath -eq 'fixture.exe'){$script:Observed=@(Get-ChildItem Env:|Where-Object {$_.Name -match '^ARPG_.*_ONLY$'}|ForEach-Object {$_.Name});switch($script:Mode){'wrong'{return '119 cases, 0 failures'};'duplicate'{return '120 cases, 0 failures','120 cases, 0 failures'};'mixed'{return '119 cases, 0 failures','120 cases, 0 failures'};default{if(Test-Path Env:ARPG_CPLAY021_LOOT_SUCTION_RUNTIME_ONLY){return '1 cases, 0 failures'};return '120 cases, 0 failures'}}} }
